final class EULAController:UIViewController{
    override func viewDidLoad(){super.viewDidLoad();modalPresentationStyle = .overFullScreen;isModalInPresentation = true;view.backgroundColor = UIColor.black.withAlphaComponent(0.6);let panel = UIView();panel.backgroundColor = .white;panel.layer.cornerRadius = 24;view.addSubview(panel);panel.snp.makeConstraints{$0.leading.trailing.equalToSuperview();$0.bottom.equalToSuperview();$0.top.equalTo(view.safeAreaLayoutGuide).offset(40)};let title = UIFactory.label("EULA",size:28,weight:.bold);title.textAlignment = .center;let text = UITextView();text.isEditable = false;text.font = .systemFont(ofSize:15);text.text = "Welcome to Viraa! To create a positive, safe, and supportive space for our wild water community, the following content is strictly prohibited on the app:\nAny content involving child harm, pornography, and other materials detrimental to minors' physical and mental health, including but not limited to text, images, or audio.\nFalse and harmful public information, including false content generated by AI or other means that disrupts public order, especially fake safety or location guides regarding wild water activities.\nViolent content, cyberbullying, hazardous behavior promotion, and any content that promotes pornography, illegal acts, or disrupts the network ecological environment. Specifically, content inciting unequipped or unsafe wild water ventures is forbidden.\nIf any of the above violations are detected, your uploaded posts, voice messages, comments, and other published content will be deleted, and your account may face restrictions or termination. By clicking the confirmation button, you agree to abide by the Terms of Use and Privacy Policy of Viraa.";let cancel = UIFactory.button("Cancel",background:AppTheme.surface,foreground:AppTheme.ink),agree = UIFactory.button("Agree",background:AppTheme.blue);cancel.addTarget(self,action:#selector(cancelTap),for:.touchUpInside);agree.addTarget(self,action:#selector(agreeTap),for:.touchUpInside);let row = UIStack